  function reviewPage() { const tasks = state.tasks.filter(task => ['submitted','revision'].includes(task.status)); return `${heading(tr('成果验收','Deliverable review'),tr('检查当前成果版本，按约定标准确认或退回。','Inspect the current submission version against the agreed criteria.'))}<section class="panel">${tasks.map(task => `<article class="review-card"><div class="review-card-top"><div><h3>${esc(task.title)}</h3><p>${esc(displayName(task.owner_id))} · ${tr('指定验收人','Reviewer')}: ${esc(displayName(task.reviewer_id))}</p></div>${badge(task.status)}</div><div class="inline-actions"><button class="btn primary small" data-live-task="${esc(task.id)}">${tr('检查成果与记录','Inspect evidence & records')} ${icon('arrow')}</button></div></article>`).join('') || empty(tr('没有等待验收或补充的成果','No deliverables await review or revision'))}</section>`; }
  function performancePage() { const accepted = state.tasks.filter(task => task.status === 'accepted'), known = accepted.map(task => state.details.get(task.id)).filter(Boolean), reviews = known.map(task => task.currentReview).filter(Boolean), average = reviews.length ? Math.round(reviews.reduce((sum,review) => sum + review.quality,0) / reviews.length) : null; return `${heading(tr('绩效参考','Performance insights'),tr('只展示有人工验收依据的数据，不生成自动人事结论。','Show evidence-backed human review data, without automated personnel decisions.'))}<div class="stats-grid">${stat(tr('已验收任务','Accepted tasks'),accepted.length,tr('当前授权范围','Your authorized scope'))}${stat(tr('已加载质量记录','Loaded quality records'),reviews.length,tr('保留版本与验收人','Version and reviewer retained'))}${stat(tr('人工质量均值','Human quality average'),average === null ? '—' : average,tr('仅已加载的当前验收版本','Loaded current accepted versions only'))}${stat(tr('综合执行分','Composite score'),'—',tr('尚未完成岗位与工作日历校准','Role and work-calendar calibration pending'))}</div>${notice(tr('质量分来自负责人确认。速度、工作时间响应与计划变更需要完整口径后才能计算；缺失数据不记零分，当前不跨岗位排名，不处理薪资或员工去留。','Quality scores come from human reviewers. Speed, working-time response and plan changes require complete definitions; missing data is not zero. This view does not rank across roles or handle salary and retention decisions.'))}<div class="live-space-top">${button(tr('读取当前验收依据','Load current review evidence'),'load-performance','','refresh')}</div><section class="panel live-space-top"><div class="panel-head"><h2>${tr('已验收任务','Accepted tasks')}</h2></div>${accepted.map(task => `<button class="todo-row" data-live-task="${esc(task.id)}"><span class="todo-body"><h3>${esc(task.title)}</h3><span class="todo-meta">${esc(displayName(task.owner_id))}</span></span><span class="badge green">${state.details.get(task.id)?.currentReview?.quality ?? '—'}</span></button>`).join('') || empty(tr('暂无人工验收记录','No human review records yet'))}</section>`; }
  function integrationPage() { const items = [[tr('钉钉身份','DingTalk identity'),state.capabilities.dingtalk],[botMode() ? tr('Grok Bot 成果评审','Grok Bot evidence assessment') : tr('Grok API 成果评审','Grok API evidence assessment'),state.capabilities.aiReview],[tr('钉钉工作通知','DingTalk work notifications'),state.capabilities.notificationDelivery]]; return `${heading(tr('集成与通知','Integrations & notifications'),tr('配置状态来自服务端；仅明确提交的操作才会执行。','Configuration is reported by the server. Only explicitly requested actions run.'))}<div class="integration-grid">${items.map(([label,value]) => `<section class="integration-card"><div class="integration-top"><div><h3>${label}</h3></div><span class="badge ${configured(value) ? 'green' : 'amber'}">${configured(value) ? tr('已配置','Configured') : tr('待配置','Not configured')}</span></div><p class="integration-description">${esc(typeof value === 'string' ? value : configured(value) ? tr('服务端已配置，请以真实调用结果为准。','Configured on the server; verify actual requests before rollout.') : tr('请由管理员在服务端配置。','An administrator must configure this on the server.'))}</p></section>`).join('')}</div><div class="live-space-top">${notice(botMode() ? tr('当前使用异步 Grok Bot 路径。使用已有 Bot 账户额度，具体配额和可用性由该账户决定；排队与分析完成分别记录。','The asynchronous Grok Bot path is selected. It uses the existing Bot account allowance; quota and availability depend on that account. Queue acceptance and assessment completion are separate states.') : tr('当前使用服务端 Grok 模型 API。调用可用性与模型费用由服务端配置和模型账户决定。','The server-side Grok model API is selected. Availability and model charges depend on server configuration and the model account.'))}</div><div class="live-space-top">${notice(tr('模型只能分析当前授权成果，提供证据、缺口与建议；负责人仍须检查实际交付物。密钥、薪资和私密配置不会在此页面显示。','The model analyzes authorized evidence and suggests findings and gaps. Managers must still inspect the actual deliverable. Keys, compensation and private settings are never displayed here.'))}</div>${manager() ? `<section class="panel live-space-top"><div class="panel-head"><h2>${tr('企业成员','Company members')}</h2>${button(tr('同步钉钉成员','Sync DingTalk members'),'sync-directory','','refresh')}</div><div class="panel-body"><p class="fine">${tr('仅同步管理员已批准的部门，更新成员身份和任务分配名单。已移出范围的账号将停用。','Sync only administrator-approved departments and update the assignment directory. Accounts outside that scope will be deactivated.')}</p><p>${tr('当前可分配成员','Assignable members')}：${state.directory.length}</p><p class="fine">${state.directory.map(user => esc(user.display_name)).join(' · ')}</p></div></section>` : ''}<section class="panel live-space-top"><div class="panel-head"><h2>${tr('工作提醒','Work reminders')}</h2>${button(tr('预览提醒','Preview reminders'),'notifications','','bell')}</div><div class="panel-body fine">${tr('预览只读取当前可见任务。发送需要负责人再次确认，服务端限定收件人为任务负责人并去重。','A preview reads only visible tasks. Sending requires manager confirmation; the server limits recipients to task owners and deduplicates requests.')}</div></section>`; }
  function stopAnalysisWatch() { if (analysisWatch) { clearTimeout(analysisWatch.timer); analysisWatch.controller?.abort(); analysisWatch = null; } }
  function closeOverlay() { stopAnalysisWatch(); drawerController?.abort(); drawerController = null; overlayGeneration++; openTaskId = null; document.getElementById('overlay-root').innerHTML = ''; document.body.style.overflow = ''; if (lastFocus && document.contains(lastFocus)) lastFocus.focus(); }
  function overlay(body, drawer = false) { lastFocus = document.activeElement; document.getElementById('overlay-root').innerHTML = `<div class="overlay ${drawer ? 'drawer-overlay' : ''}" data-live-overlay><section class="${drawer ? 'drawer' : 'modal'}" role="dialog" aria-modal="true" aria-labelledby="live-dialog-title" tabindex="-1">${body}</section></div>`; document.body.style.overflow = 'hidden'; requestAnimationFrame(() => document.querySelector('#overlay-root [role="dialog"]')?.focus()); }
